using System;
using System.Linq;
using NUnit.Framework;
namespace Brodun.Tests {
public sealed class Card70Tests : RulesTest {
 BattleRuntime Make(CharacterId hero,params string[] ids) {
  var modern=Card70Catalog.Apply(Data);var run=new RunState(modern,hero,17);
  run.deck.Clear();int i=0;foreach(var id in ids)run.deck.Add(new CardInstance("test-"+i++,id.TrimEnd('+'),id.EndsWith("+")?1:0));
  var b=new BattleRuntime(modern,run,DungeonRuntime.Enter(run,"r1"));b.Deck.Draw(10);b.Enemy.CurrentHP=10000;b.Enemy.Block=0;b.Energy=6;return b;
 }
 void Play(BattleRuntime b,string id,CardPlayOptions o=null){var c=b.Deck.Hand.First(x=>x.CardId==id);Assert.IsTrue(b.PlayCard(c.InstanceId,o),id);}
 [Test] public void CatalogAndClassPoolsAreExact(){var d=Card70Catalog.Apply(Data);Assert.AreEqual(70,d.Cards.Count);Assert.AreEqual(70,d.Cards.Select(c=>c.Id).Distinct().Count());foreach(CharacterId hero in Enum.GetValues(typeof(CharacterId))){var r=new RunState(d,hero,1);Assert.AreEqual(10,r.Deck.Count);Assert.AreEqual(32,d.Cards.Count(c=>c.Rarity!=CardRarity.Basic&&(!c.Owner.HasValue||c.Owner==hero)));Assert.AreEqual(hero==CharacterId.Priest?31:32,Card70Rewards.Eligible(d,r).Count());}}
 [Test] public void EveryDefinitionResolvesBothUpgradeStates(){foreach(var id in Card70Catalog.Ids)foreach(bool up in new[]{false,true}){var d=Card70Catalog.Card(id,up);var b=Make(d.Owner??CharacterId.Warrior,id+(up?"+":""),id=="W01"?"N02":"W01");b.Resonance=12;b.Grace=10;b.Brand=8;b.Block=20;b.Strength=4;var other=b.Deck.Hand.Single(c=>c.CardId!=id);var o=new CardPlayOptions{SelectedInstance=other.InstanceId};Play(b,id,o);if(b.PendingDiscard)Assert.IsTrue(b.ResolveDiscard(b.Deck.Hand[0].InstanceId));Assert.That(b.Energy,Is.InRange(0,6));Assert.GreaterOrEqual(b.Block,0);}}
 [Test] public void StrengthUltimateUsesSavedStrengthAndLeavesBlock(){var b=Make(CharacterId.Warrior,"W15+","W12","N12","W18");b.Energy=3;b.Strength=4;Play(b,"W15");Play(b,"W12");Play(b,"N12");Play(b,"W18");Assert.AreEqual(76,b.LastCardResult.Damage);Assert.AreEqual(22,b.Block);Assert.AreEqual(0,b.Strength);Assert.AreEqual(1,b.Energy);}
 [Test] public void HalfBlockAttackDoesNotRefund(){var b=Make(CharacterId.Warrior,"W09");b.Energy=3;b.Block=21;Play(b,"W09");Assert.AreEqual(28,b.LastCardResult.Damage);Assert.AreEqual(11,b.Block);Assert.AreEqual(1,b.Energy);}
 [Test] public void WarriorSharedCardsBridgeBothResources(){var b=Make(CharacterId.Warrior,"W07","W10","W12");b.Strength=3;b.Energy=3;Play(b,"W07");Play(b,"W10");Assert.AreEqual(8,b.LastCardResult.Damage);Play(b,"W12");Assert.AreEqual(27,b.Block);Assert.AreEqual(4,b.Strength);}
 [Test] public void BlockRetainsOnlyPostHitRemainder(){var b=Make(CharacterId.Warrior,"W13","W11","W16");Play(b,"W13");b.Block=12;Play(b,"W11");Assert.AreEqual(34,b.Block);b.Enemy.Status.Strength=0;int expected=Math.Max(0,34-(b.CurrentIntent.Type==IntentType.Attack?b.CurrentIntent.Amount*b.CurrentIntent.Hits:0));b.EndTurn();Assert.AreEqual(expected,b.Block);Assert.IsTrue(b.Deck.Hand.Any(c=>c.CardId=="W16"));Play(b,"W16");Assert.AreEqual(8+expected*2,b.LastCardResult.Damage);Assert.AreEqual(0,b.Block);}
 [Test] public void ArcaneBurstHonorsEnergyCapAndDebt(){var b=Make(CharacterId.Mage,"M12","N12","N15+","M17");b.Resonance=4;b.Energy=3;Play(b,"M12");Play(b,"N12");Play(b,"N15");Play(b,"M17");Assert.AreEqual(108,b.LastCardResult.Damage);Assert.AreEqual(0,b.Resonance);b.EndTurn();Assert.AreEqual(2,b.Energy);}
 [Test] public void ResonanceSpendingSuppliesHandAndDefense(){var b=Make(CharacterId.Mage,"M12","M16","M18","M11");b.Resonance=6;b.Energy=3;Play(b,"M12");Play(b,"M16");Play(b,"M18");Play(b,"M11",new CardPlayOptions{ExtraEnergy=true});Assert.AreEqual(12,b.Block);Assert.AreEqual(28,b.LastCardResult.Damage);Assert.AreEqual(0,b.Energy);}
 [Test] public void ExpensiveAmplifierAppliesOnceToMultiHit(){var b=Make(CharacterId.Mage,"M13","M11");Play(b,"M13");Play(b,"M11",new CardPlayOptions{ExtraEnergy=true});Assert.AreEqual(44,b.LastCardResult.Damage);}
 [Test] public void CrossAndConsumerIncludeOwnResonance(){var b=Make(CharacterId.Mage,"M08","M15","M09+");Play(b,"M08");Play(b,"M15");b.Resonance=7;b.Energy=3;Play(b,"M09");Assert.AreEqual(46,b.LastCardResult.Damage);Assert.AreEqual(0,b.Resonance);Assert.AreEqual(2,b.Energy);}
 [Test] public void BrandAmplificationCapsThenRebuilds(){var b=Make(CharacterId.Priest,"P09","P10","P17+","P15+");Play(b,"P09");b.Brand=3;b.Energy=3;Play(b,"P10");Play(b,"P17");Play(b,"P15");Assert.AreEqual(56,b.LastCardResult.Damage);Assert.AreEqual(1,b.Brand);Assert.AreEqual(3,b.Block);}
 [Test] public void GraceFinisherDoesNotDoubleCountHealing(){var b=Make(CharacterId.Priest,"P08","N07","P05","P16+");Play(b,"P08");Play(b,"N07");b.Grace=4;b.Run.CurrentHP-=10;b.Energy=3;Play(b,"P05");Play(b,"P16");Assert.AreEqual(34,b.LastCardResult.Damage);Assert.AreEqual(0,b.Grace);Assert.AreEqual(6,b.Block);Assert.AreEqual(b.Run.MaxHP,b.Run.CurrentHP);}
 [Test] public void RepeatHealingUsesGraceBeforeHealing(){var b=Make(CharacterId.Priest,"P12");b.Grace=6;b.Run.CurrentHP-=20;int hp=b.Run.CurrentHP;Play(b,"P12");Assert.AreEqual(6,b.Run.CurrentHP-hp);Assert.AreEqual(7,b.Grace);}
 [Test] public void FullHealthCannotFarmGrace(){var b=Make(CharacterId.Priest,"P08","P12");Play(b,"P08");Play(b,"P12");Assert.AreEqual(0,b.Grace);}
 [Test] public void UpgradedMarkAtCapStillLeavesExactlyOneNewMark(){var b=Make(CharacterId.Priest,"P03+");b.Brand=8;Play(b,"P03");Assert.AreEqual(8,b.Brand);}
 [Test] public void InvalidPaymentAndSelectionAreAtomic(){var b=Make(CharacterId.Mage,"M16","N10","W01");int energy=b.Energy;Assert.IsFalse(b.PlayCard(b.Deck.Hand.Single(c=>c.CardId=="M16").InstanceId));Assert.IsFalse(b.PlayCard(b.Deck.Hand.Single(c=>c.CardId=="N10").InstanceId,new CardPlayOptions{SelectedInstance="missing"}));Assert.AreEqual(energy,b.Energy);Assert.AreEqual(3,b.Deck.Hand.Count);}
 [Test] public void DrawingCardCannotDrawItselfAndDiscardNeedsChoice(){var b=Make(CharacterId.Warrior,"N01");Play(b,"N01");Assert.IsFalse(b.PendingDiscard);Assert.AreEqual(0,b.Deck.Hand.Count);var c=Make(CharacterId.Warrior,"N01","W01");Play(c,"N01");Assert.IsTrue(c.PendingDiscard);Assert.IsFalse(c.EndTurn());Assert.IsTrue(c.ResolveDiscard(c.Deck.Hand[0].InstanceId));}
 [Test] public void PowerDoesNotRefundItsOwnInstallation(){var b=Make(CharacterId.Warrior,"N14","W13");b.Energy=3;Play(b,"N14");Assert.AreEqual(1,b.Energy);b.Energy=3;Play(b,"W13");Assert.AreEqual(2,b.Energy);}
 [Test] public void RewardAndShopNeverOfferOtherClassesOrBasics(){foreach(CharacterId hero in Enum.GetValues(typeof(CharacterId))){var d=Card70Catalog.Apply(Data);for(uint seed=1;seed<=40;seed++){var r=new RunState(d,hero,seed);DungeonRuntime.Enter(r,"r1");var reward=RewardResolver.Create(d,r);Assert.AreEqual(3,reward.Candidates.Count);Assert.AreEqual(3,reward.Candidates.Distinct().Count());foreach(var id in reward.Candidates)Assert.IsTrue(Card70Rewards.CanAcquire(d,r,id));}}}
 [Test] public void CopyLimitsIncludeStarterNonBasics(){var d=Card70Catalog.Apply(Data);var r=new RunState(d,CharacterId.Warrior,1);Assert.IsTrue(Card70Rewards.CanAcquire(d,r,"W03"));r.AddCard("W03");Assert.IsFalse(Card70Rewards.CanAcquire(d,r,"W03"));Assert.IsFalse(Card70Rewards.CanAcquire(d,r,"M03"));Assert.IsFalse(Card70Rewards.CanAcquire(d,r,"W01"));}
 [Test] public void ScheduledBlockArrivesAfterResetAndRetainedCardSurvives(){var b=Make(CharacterId.Warrior,"N05+","W01");var target=b.Deck.Hand.First(c=>c.CardId=="W01");Play(b,"N05",new CardPlayOptions{SelectedInstance=target.InstanceId});b.EndTurn();Assert.AreEqual(4,b.Energy);Assert.AreEqual(4,b.Block);Assert.AreEqual(1,b.Deck.Hand.Count);Assert.AreEqual(target.InstanceId,b.Deck.Hand[0].InstanceId);}
 [Test] public void RepeatedDrawStartsNextTurnAndHandCapsAtTen(){var b=Make(CharacterId.Warrior,new[]{"N13","W01","W01","W01","W01","W01","W01","W01","W01","W01"});Assert.AreEqual(10,b.Deck.Hand.Count);b.Deck.Draw(100);Assert.AreEqual(10,b.Deck.Hand.Count);Play(b,"N13");b.EndTurn();Assert.AreEqual(5,b.Deck.Hand.Count);}
 [Test] public void BrandHealingBridgeTriggersOnceAndNotAtFullHealth(){var b=Make(CharacterId.Priest,"P14","P04","P12");Play(b,"P14");b.Brand=1;b.Run.CurrentHP-=8;Play(b,"P04");Assert.AreEqual(1,b.Grace);Assert.AreEqual(3,b.Block);Play(b,"P12");Assert.AreEqual(1,b.Grace);Assert.AreEqual(3,b.Block);}
 [Test] public void ShopUpgradeAndRemovePersistAndChargeOnce(){var d=Card70Catalog.Apply(Data);var r=new RunState(d,CharacterId.Warrior,1);r.ActiveRoom="shop-test";r.AddGold(100);var room=new RoomRuntime(d,r,new RoomNode("shop-test",RoomType.Event,1,50,new string[0],EventKind.Shop));string upgrade=r.Deck[0].InstanceId,remove=r.Deck[1].InstanceId;Assert.IsTrue(room.Upgrade(upgrade));Assert.AreEqual(1,r.Deck[0].UpgradeLevel);Assert.IsFalse(room.Upgrade(upgrade));Assert.IsTrue(room.Remove(remove));Assert.AreEqual(30,r.Gold);Assert.AreEqual(9,r.Deck.Count);Assert.IsFalse(room.Remove(r.Deck[1].InstanceId));}
 [Test] public void RestUpgradeConsumesRecoveryChoice(){var d=Card70Catalog.Apply(Data);var r=new RunState(d,CharacterId.Warrior,1);r.ActiveRoom="rest-test";var room=new RoomRuntime(d,r,new RoomNode("rest-test",RoomType.Event,1,50,new string[0],EventKind.RestSite));Assert.IsTrue(room.Upgrade(r.Deck[0].InstanceId));Assert.IsFalse(room.Choose(RoomChoice.Rest));Assert.AreEqual(0,r.Gold);}
 [Test] public void OnlyOwnRetainKeywordsRetainTheCard(){Assert.IsFalse(Card70Catalog.Card("N05").Retains);Assert.IsTrue(Card70Catalog.Card("W18").Retains);Assert.IsTrue(Card70Catalog.Card("P15").Retains);}
 [Test] public void ModernBossOffersHighRewardBeforeCompletingRun(){var d=Card70Catalog.Apply(Data);var r=new RunState(d,CharacterId.Warrior,1);r.ActiveRoom=r.CurrentNode="boss";var context=new Brodun.Flow.BattleContext(d,r,DungeonRuntime.Node(r,"boss"));context.Runtime.Deck.Draw(10);context.Runtime.Enemy.CurrentHP=1;context.Runtime.Enemy.Block=0;var c=context.Runtime.Deck.Hand.First(x=>x.CardId=="W01");Assert.IsTrue(context.Play(c.InstanceId));context.FinishActionPresentation();Assert.IsTrue(context.OpenReward());Assert.AreEqual(3,context.Runtime.Reward.Candidates.Count);Assert.IsTrue(context.Runtime.Reward.Candidates.All(id=>d.Card(id).Rarity==CardRarity.High));Assert.IsTrue(context.ResolveReward(RewardType.Skip));Assert.AreEqual(RunStatus.Complete,r.Status);}
}
}
